const body = $json.body || $json;
const publicationJobId = String(body.publicationJobId || body.publication_job_id || '').trim();
const requestedPlatform = String(body.platform || 'instagram').trim();
const finalCaption = body.finalCaption || body.final_caption || null;
const hashtags = Array.isArray(body.hashtags) ? body.hashtags : null;
const publishingNotes = body.publishingNotes || body.publishing_notes || null;
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(publicationJobId)) {
  return [{ json: { query: "SELECT false AS ok, 'publicationJobId is required' AS error;" } }];
}
const overrides = { finalCaption, hashtags, platform: requestedPlatform, publishingNotes };
const query = `
WITH job AS (
  SELECT *
  FROM publication_jobs
  WHERE publication_job_id = ${sql(publicationJobId)}::uuid
  LIMIT 1
), selected_asset AS (
  SELECT car.*
  FROM canonical_asset_registry car
  JOIN job pj ON car.asset_id::text = pj.metadata->>'selectedAssetId'
  LIMIT 1
)
SELECT
  true AS ok,
  pj.publication_job_id AS "publicationJobId",
  pj.avatar,
  pj.scene,
  pj.format,
  pj.objective,
  pj.business_profile AS "businessProfile",
  pj.asset_type AS "assetType",
  pj.status,
  pj.brief,
  pj.prompt_pack AS "promptPack",
  pj.publishing_pack AS "publishingPack",
  pj.metadata,
  pj.created_at AS "createdAt",
  pj.updated_at AS "updatedAt",
  ac.display_name AS "avatarDisplayName",
  ac.avatar_short AS "avatarShort",
  sc.display_name AS "sceneDisplayName",
  COALESCE(sa.asset_id, pj.metadata->>'selectedAssetId') AS "selectedAssetId",
  sa.bucket AS "selectedAssetBucket",
  sa.object_path AS "selectedAssetObjectPath",
  sa.status AS "selectedAssetStatus",
  ${sql(JSON.stringify(overrides))}::jsonb AS "exportOverrides"
FROM job pj
LEFT JOIN selected_asset sa ON true
LEFT JOIN avatar_catalog ac ON ac.avatar = pj.avatar
LEFT JOIN scene_catalog sc ON sc.scene = pj.scene
LIMIT 1;
`;
return [{ json: { query } }];

function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) { return sql(JSON.stringify(value ?? {})) + '::jsonb'; }
function parseJson(value, fallback) {
