  return value;
}
function toArray(value, fallback = []) {
  if (Array.isArray(value)) return value.map(String).filter(Boolean);
  if (typeof value === 'string' && value.trim()) return value.split(/[\n,;]/).map((x) => x.trim()).filter(Boolean);
  return fallback;
}
