  ? '/minio/' + row.selectedAssetBucket + '/' + row.selectedAssetObjectPath
  : null;
const publishingExport = {
  publicationJobId: row.publicationJobId,
  platform,
  status: 'ready-to-publish',
  imageUrl,
  assetId: row.selectedAssetId || null,
  bucket: row.selectedAssetBucket || null,
  objectPath: row.selectedAssetObjectPath || null,
  finalCaption,
  hashtags,
  storyText: toArray(publishingPack.storyText || publishingPack.story_text, []),
  ctaOptions: toArray(publishingPack.ctaOptions || publishingPack.cta_options, []),
  publishingNotes: String(overrides.publishingNotes || publishingPack.publishingNotes || publishingPack.publishing_notes || 'Manual publishing pack. Review image and copy before public posting.').trim(),
  metadata: {
    avatar: row.avatar,
    avatarDisplayName: row.avatarDisplayName,
    scene: row.scene,
