    'Publish manually on the selected platform after final human review.',
    'After publishing, use US-009 to record the published URL.'
  ],
  exportedAt: new Date().toISOString()
};
const query = `
UPDATE publication_jobs
SET
  status = 'ready-to-publish',
  error_message = NULL,
  updated_at = now(),
  metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
    'publishingExport', ${sqlJson(publishingExport)},
    'publishingExportedAt', now(),
    'publishingPlatform', ${sql(platform)}
  )
WHERE publication_job_id = ${sql(row.publicationJobId)}::uuid
RETURNING
  true AS ok,
  publication_job_id AS "publicationJobId",
  avatar,
  scene,
  format,
  objective,
  business_profile AS "businessProfile",
  asset_type AS "assetType",
  status,
  brief,
  prompt_pack AS "promptPack",
  publishing_pack AS "publishingPack",
  metadata->'publishingExport' AS "publishingExport",
  created_at AS "createdAt",
  updated_at AS "updatedAt";
`;
return [{ json: { query } }];

